export const DEFAULT_SITE_ORIGIN = 'https://appwrite.io'

export function getSitemapSiteOrigin(): string {
  const fromEnv =
    typeof process !== 'undefined'
      ? process.env.VITE_SITE_ORIGIN?.trim()
      : undefined
  return (fromEnv || DEFAULT_SITE_ORIGIN).replace(/\/+$/, '')
}

/** Max URLs per sitemap file (protocol limit is 50,000). */
export const SITEMAP_MAX_URLS_PER_FILE = 50_000
import { createIsomorphicFn } from '@tanstack/react-start'
import { getRequestUrl } from '@tanstack/react-start/server'
import { getSitemapSiteOrigin } from '@/lib/sitemap/config'

export function getDefaultSiteOrigin(): string {
  return getSitemapSiteOrigin()
}

/** Origin for absolute SEO/asset URLs. Prefers the active request host (incl. port). */
export function getSeoSiteOrigin(siteOrigin?: string): string {
  return (siteOrigin ?? getRequestSiteOrigin()).replace(/\/+$/, '')
}

export function resolveSiteAssetUrl(path: string, siteOrigin?: string): string {
  if (!path.startsWith('/')) return path
  return `${getSeoSiteOrigin(siteOrigin)}${path}`
}

function isLoopbackHostname(hostname: string): boolean {
  return (
    hostname === 'localhost' ||
    hostname === '127.0.0.1' ||
    hostname === '[::1]' ||
    hostname === '::1'
  )
}

function normalizeSiteOrigin(origin: string): string {
  return origin.replace(/\/+$/, '')
}

/**
 * TanStack prerender runs against loopback during production builds. Static HTML
 * must not bake `http://localhost` into og:url / og:image; use the public origin.
 */
export function resolveServerSiteOrigin(
  requestOrigin: string,
  isProd: boolean = import.meta.env.PROD,
): string {
  try {
    const { hostname } = new URL(requestOrigin)
    if (!isLoopbackHostname(hostname)) {
      return normalizeSiteOrigin(requestOrigin)
    }
  } catch {
    return getDefaultSiteOrigin()
  }

  if (isProd) {
    return getDefaultSiteOrigin()
  }

  return normalizeSiteOrigin(requestOrigin)
}

export const getRequestSiteOrigin = createIsomorphicFn()
  .server(() => {
    try {
      const origin = getRequestUrl({
        xForwardedHost: true,
        xForwardedProto: true,
      }).origin
      return resolveServerSiteOrigin(origin)
    } catch {
      return getDefaultSiteOrigin()
    }
  })
  .client(() => window.location.origin)
import { parseCoverRenderData } from '@/lib/cover-generator/parse-params'
import { DEFAULT_COVER_THEME_ID, type CoverThemeId } from '@/lib/cover-generator/themes'
import type { CoverRenderData } from '@/lib/cover-generator/types'
import { getSeoSiteOrigin } from '@/lib/marketing/site-origin'

export const OG_IMAGE_PATH = '/og/image.png'
export const OG_COVER_PATH = '/og/cover.jpg'

/** Classic Open Graph canvas (≈1.91:1). Distinct from the 16:9 blog cover artboard. */
export const OG_IMAGE_WIDTH = 1200
export const OG_IMAGE_HEIGHT = 630

export type OgImageParams = {
  title: string
  subtitle?: string
  eyebrow?: string
  cta?: string
  theme?: CoverThemeId
}

const OG_TITLE_MAX_LENGTH = 120
const OG_SUBTITLE_MAX_LENGTH = 160
const OG_EYEBROW_MAX_LENGTH = 40
const OG_CTA_MAX_LENGTH = 32

function truncateOgText(value: string, maxLength: number): string {
  const trimmed = value.trim()
  if (trimmed.length <= maxLength) return trimmed
  return `${trimmed.slice(0, maxLength - 1).trimEnd()}…`
}

export function buildOgImageUrl(
  params: OgImageParams,
  siteOrigin?: string,
): string {
  const searchParams = new URLSearchParams()
  searchParams.set('title', truncateOgText(params.title, OG_TITLE_MAX_LENGTH))

  if (params.subtitle?.trim()) {
    searchParams.set(
      'subtitle',
      truncateOgText(params.subtitle, OG_SUBTITLE_MAX_LENGTH),
    )
  }

  if (params.eyebrow?.trim()) {
    searchParams.set(
      'eyebrow',
      truncateOgText(params.eyebrow, OG_EYEBROW_MAX_LENGTH),
    )
  }

  if (params.cta?.trim()) {
    searchParams.set('cta', truncateOgText(params.cta, OG_CTA_MAX_LENGTH))
  }

  if (params.theme) {
    searchParams.set('theme', params.theme)
  }

  return `${getSeoSiteOrigin(siteOrigin)}${OG_IMAGE_PATH}?${searchParams.toString()}`
}

/** X and LinkedIn cannot render AVIF cards, so AVIF covers are served as JPEG. */
export function buildOgCoverUrl(cover: string, siteOrigin?: string): string {
  if (!cover.startsWith('/')) return cover

  const origin = getSeoSiteOrigin(siteOrigin)
  if (!cover.endsWith('.avif')) return `${origin}${cover}`

  return `${origin}${OG_COVER_PATH}?${new URLSearchParams({ path: cover }).toString()}`
}

export function parseOgImageRenderData(
  searchParams: URLSearchParams,
): CoverRenderData {
  const params = new URLSearchParams(searchParams)
  params.set('template', 'simple-title')
  params.set('format', 'png')
  params.set('width', String(OG_IMAGE_WIDTH))
  params.set('height', String(OG_IMAGE_HEIGHT))

  if (!params.get('theme')?.trim()) {
    params.set('theme', DEFAULT_COVER_THEME_ID)
  }

  return parseCoverRenderData(params)
}
/** TanStack Router head `links` entry for canonical URLs (not valid inside `meta`). */
export type CanonicalLink = {
  rel: 'canonical'
  href: string
}

type MetaTag = Record<string, string>

function isLegacyCanonicalLinkMeta(tag: MetaTag): boolean {
  return tag.tag === 'link' && tag.rel === 'canonical' && Boolean(tag.href)
}

export function getCanonicalLink(href: string): CanonicalLink {
  return { rel: 'canonical', href }
}

export function canonicalLinks(href?: string): CanonicalLink[] {
  return href ? [getCanonicalLink(href)] : []
}

/**
 * Build route `head()` payload from SEO meta tags. Canonical href comes from
 * `og:url` unless overridden (marketing pages pass an explicit URL).
 */
export function asRouteHead(
  metaTags: readonly MetaTag[],
  options?: { canonicalHref?: string },
): { meta: MetaTag[]; links: CanonicalLink[] } {
  const meta = metaTags.filter((tag) => !isLegacyCanonicalLinkMeta(tag))
  const canonicalHref =
    options?.canonicalHref?.trim() ||
    metaTags.find((tag) => tag.property === 'og:url')?.content?.trim() ||
    metaTags.find(isLegacyCanonicalLinkMeta)?.href?.trim()

  return {
    meta: [...meta],
    links: canonicalLinks(canonicalHref),
  }
}
